import { API } from '../api.js?v=20260908-bbs-navigation-loading-r1';
import { escHtml, showToast, showError } from '../ui.js?v=20260602-mobile-nav-m53';

const state = { health: null, campaigns: [], selected: null, rules: [], preview: null, employees: [], editing: null, questions: [], dashboard: null, submissions: [], nominations: [], scoring: null, operations: null, notificationPreview: null, stages: [], criteria: [], juryAssignments: [], resultSnapshots: [], governance: null, handoffPreview: null };
const questionTypes=['single_choice','multiple_choice','yes_no_abstain','rating','likert','ranking','matrix','allocation','token','short_text','long_text','date_time','employee_picker','organization_picker','file_upload'];
const optionQuestionTypes=new Set(['single_choice','multiple_choice','yes_no_abstain','likert','ranking','matrix','allocation','token']);
const types = ['popular_vote','secret_election','survey','poll','feedback','nomination','award','submission_challenge','jury_scoring','hybrid_scoring','ranking','prioritization','allocation','resolution','petition','event_choice','risk_perception','knowledge_check','multi_stage'];
const privacy = ['identified','confidential','anonymous','secret_ballot'];

function field(id, label, value = '', type = 'text') { return `<label class="block text-xs font-bold text-slate-600">${label}<input id="${id}" type="${type}" value="${escHtml(value ?? '')}" class="mt-1 min-h-[44px] w-full rounded-lg border border-slate-200 px-3 text-sm"></label>`; }
function options(values, selected) { return values.map(value => `<option value="${value}" ${value===selected?'selected':''}>${value}</option>`).join(''); }

function render(container) {
    if (!state.health?.ready) {
        container.innerHTML = `<section class="rounded-xl border border-amber-200 bg-amber-50 p-6"><p class="text-xs font-black uppercase tracking-widest text-amber-700">Safety Vote Phase 3</p><h2 class="mt-2 text-lg font-black text-slate-800">Schema ยังไม่พร้อม</h2><p class="mt-2 text-sm text-slate-600">ต้องใช้ explicit additive migration ก่อน Runtime จะเปิด Survey / Submission API ระบบจะไม่สร้างตารางให้อัตโนมัติ</p><pre class="mt-4 overflow-auto rounded-lg bg-white p-3 text-xs">${escHtml(JSON.stringify(state.health||{},null,2))}</pre></section>`;
        return;
    }
    const e = state.editing || { campaignCode:'',titleTh:'',titleEn:'',campaignType:'popular_vote',privacyMode:'identified',resultVisibility:'hidden_until_close',discoveryMode:'eligible_only',summary:'',description:'',rulesText:'',privacyThreshold:5 };
    const list = state.campaigns.map(row => `<button type="button" onclick="window._svSelect(${Number(row.id)})" class="w-full rounded-xl border ${Number(state.selected?.campaign?.id)===Number(row.id)?'border-emerald-400 bg-emerald-50':'border-slate-200 bg-white'} p-4 text-left"><div class="flex justify-between gap-3"><div><p class="text-sm font-black text-slate-800">${escHtml(row.TitleTh)}</p><p class="mt-1 text-xs text-slate-500">${escHtml(row.CampaignCode)} · ${escHtml(row.CampaignType)} · ${escHtml(row.PrivacyMode)}</p></div><span class="rounded-full bg-slate-100 px-2 py-1 text-[10px] font-black">${escHtml(row.Status)}</span></div></button>`).join('') || '<p class="rounded-xl border border-dashed p-6 text-center text-sm text-slate-400">ยังไม่มี Draft Campaign</p>';
    const rulesHtml = state.rules.map((rule,index)=>`<div class="flex items-center justify-between gap-2 rounded-lg border bg-white p-3 text-xs"><span><strong>${escHtml(rule.effect)}</strong> ${escHtml(rule.attributeKey)} ${escHtml(rule.operator)} ${escHtml((rule.values||[]).join(', ')||'—')}</span><button type="button" onclick="window._svRemoveRule(${index})" class="min-h-[44px] px-3 font-bold text-rose-600">ลบ</button></div>`).join('') || '<p class="text-xs text-slate-400">ยังไม่มีกฎ ผู้มีสิทธิ์จะเป็นศูนย์จนกว่าจะเพิ่ม Include rule</p>';
    container.innerHTML = `<div class="animate-fade-in space-y-5">
      <section class="rounded-xl border border-emerald-200 bg-gradient-to-r from-emerald-900 to-teal-700 p-6 text-white"><p class="text-xs font-black uppercase tracking-widest text-emerald-200">Core Activity Vote MVP · Contract ${escHtml(state.health.contractVersion||'')}</p><h2 class="mt-2 text-xl font-black">Safety Vote Administration</h2><p class="mt-2 max-w-3xl text-sm text-emerald-100">จัดการ Draft, Question Builder, Eligibility freeze, private gallery, lifecycle, dashboard และ export โดย Admin ไม่สามารถแก้คะแนนที่รับแล้ว</p><div class="mt-4 flex flex-wrap gap-2 text-xs"><span class="rounded-full bg-white/15 px-3 py-1.5">Schema ${escHtml(state.health.schemaVersion||'')}</span><span class="rounded-full bg-white/15 px-3 py-1.5">User module: ${state.health.moduleEnabled?'Enabled':'Disabled'}</span></div></section>
      <div class="grid grid-cols-1 gap-5 xl:grid-cols-[360px_1fr]">
        <section class="space-y-3"><div class="flex items-center justify-between"><h3 class="font-black text-slate-800">Draft Campaigns</h3><button type="button" onclick="window._svNew()" class="min-h-[44px] rounded-lg bg-emerald-600 px-4 text-xs font-black text-white">+ สร้าง Draft</button></div>${list}</section>
        <section class="rounded-xl border border-slate-200 bg-white p-5 shadow-sm"><h3 class="font-black text-slate-800">${state.editing?.id?'แก้ไข Draft':'สร้าง Draft Campaign'}</h3><div class="mt-4 grid grid-cols-1 gap-3 md:grid-cols-2">${field('sv-code','Campaign Code',e.campaignCode||e.CampaignCode)}${field('sv-title-th','ชื่อภาษาไทย',e.titleTh||e.TitleTh)}${field('sv-title-en','ชื่อภาษาอังกฤษ',e.titleEn||e.TitleEn)}<label class="text-xs font-bold text-slate-600">ประเภท<select id="sv-type" class="mt-1 min-h-[44px] w-full rounded-lg border px-3">${options(types,e.campaignType||e.CampaignType)}</select></label><label class="text-xs font-bold text-slate-600">Privacy<select id="sv-privacy" class="mt-1 min-h-[44px] w-full rounded-lg border px-3">${options(privacy,e.privacyMode||e.PrivacyMode)}</select></label><label class="text-xs font-bold text-slate-600">การแสดงผล<select id="sv-result" class="mt-1 min-h-[44px] w-full rounded-lg border px-3">${options(['live','admin_only','hidden_until_close','certified_only','published'],e.resultVisibility||e.ResultVisibility)}</select></label>${field('sv-threshold','Privacy threshold',e.privacyThreshold||e.PrivacyThreshold||5,'number')}</div><label class="mt-3 block text-xs font-bold text-slate-600">สรุป<textarea id="sv-summary" rows="2" class="mt-1 w-full rounded-lg border p-3">${escHtml(e.summary||e.Summary||'')}</textarea></label><div class="mt-4 flex gap-2"><button type="button" onclick="window._svSave()" class="min-h-[44px] rounded-lg bg-emerald-600 px-5 text-xs font-black text-white">บันทึก Draft</button><button type="button" onclick="window._svNew()" class="min-h-[44px] rounded-lg border px-4 text-xs font-bold">ล้างฟอร์ม</button></div></section>
      </div>
      ${state.selected?`<section class="rounded-xl border border-sky-200 bg-sky-50/40 p-5"><p class="text-xs font-black uppercase tracking-widest text-sky-700">Eligibility Draft / Preview</p><h3 class="mt-1 font-black text-slate-800">${escHtml(state.selected.campaign.TitleTh)}</h3><div class="mt-4 grid grid-cols-1 gap-3 md:grid-cols-4"><select id="sv-rule-effect" class="min-h-[44px] rounded-lg border px-3"><option>include</option><option>exclude</option></select><select id="sv-rule-attr" class="min-h-[44px] rounded-lg border px-3">${options(['all','employee_id','department_id','safety_unit_id','position_id','role','team'],'all')}</select><select id="sv-rule-op" class="min-h-[44px] rounded-lg border px-3">${options(['IN','EQUALS','NOT_IN','NOT_EQUALS','IS_EMPTY','IS_NOT_EMPTY'],'IN')}</select><input id="sv-rule-values" class="min-h-[44px] rounded-lg border px-3" placeholder="ค่า คั่นด้วย comma"></div><button type="button" onclick="window._svAddRule()" class="mt-3 min-h-[44px] rounded-lg border border-sky-300 bg-white px-4 text-xs font-black text-sky-700">เพิ่มกฎ</button><div class="mt-3 space-y-2">${rulesHtml}</div><div class="mt-4 flex flex-wrap gap-2"><button type="button" onclick="window._svSaveRules()" class="min-h-[44px] rounded-lg bg-sky-700 px-4 text-xs font-black text-white">บันทึกกฎ</button><button type="button" onclick="window._svPreview()" class="min-h-[44px] rounded-lg bg-emerald-600 px-4 text-xs font-black text-white">Preview ผู้มีสิทธิ์</button></div>${state.preview?`<div class="mt-4 grid grid-cols-2 gap-3 md:grid-cols-4">${[['ผู้มีสิทธิ์',state.preview.eligibleCount],['Account Ready',state.preview.accountReadyCount],['Warnings',state.preview.warningCount],['แสดงตัวอย่าง',state.preview.rows?.length||0]].map(([l,v])=>`<div class="rounded-xl border bg-white p-3"><p class="text-xl font-black">${Number(v||0).toLocaleString()}</p><p class="text-xs text-slate-500">${l}</p></div>`).join('')}</div>`:''}</section>
      <section class="rounded-xl border border-slate-200 bg-white p-5"><div class="flex flex-col gap-3 md:flex-row md:items-end md:justify-between"><div><p class="text-xs font-black uppercase tracking-widest text-slate-500">Master Data Picker</p><p class="mt-1 text-sm text-slate-600">อ่านจาก System Console เท่านั้น</p></div><div class="flex gap-2"><input id="sv-master-q" class="min-h-[44px] rounded-lg border px-3" placeholder="ID, ชื่อ, แผนก"><button type="button" onclick="window._svMasterSearch()" class="min-h-[44px] rounded-lg bg-slate-800 px-4 text-xs font-black text-white">ค้นหา</button></div></div><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[720px] text-sm"><thead class="bg-slate-50 text-xs text-slate-500"><tr><th class="p-3 text-left">Employee</th><th class="p-3 text-left">Department / Unit</th><th class="p-3 text-left">Position</th><th class="p-3 text-left">Account</th></tr></thead><tbody>${state.employees.map(row=>`<tr class="border-t"><td class="p-3"><strong>${escHtml(row.employeeId)}</strong><br><span class="text-xs">${escHtml(row.employeeName)}</span></td><td class="p-3">${escHtml(row.departmentName)} / ${escHtml(row.safetyUnitName)}</td><td class="p-3">${escHtml(row.positionName)}</td><td class="p-3">${row.accountReady?'<span class="text-emerald-700">READY</span>':`<span class="text-amber-700">${escHtml(row.onboardingStatus)}</span>`}</td></tr>`).join('')||'<tr><td colspan="4" class="p-6 text-center text-slate-400">ค้นหา Employee Master เพื่อแสดงข้อมูล</td></tr>'}</tbody></table></div></section>`:''}
    </div>`;
    if (state.editing?.id) {
        const resetButton = container.querySelector('button[onclick="window._svNew()"]');
        resetButton?.insertAdjacentHTML('beforebegin','<button type="button" onclick="window._svVoid()" class="min-h-[44px] rounded-lg border border-rose-300 px-4 text-xs font-bold text-rose-700">ยกเลิก Draft</button>');
        renderPhase2(container);
        renderPhase4(container);
        renderPhase4Scoring(container);
        renderPhase5(container);
        renderPhase6(container);
        renderPhase7(container);
    }
}

function renderPhase2(container){const c=state.selected?.campaign;if(!c)return;const panel=document.createElement('section');panel.className='rounded-xl border border-violet-200 bg-violet-50/40 p-5';panel.innerHTML=`<p class="text-xs font-black uppercase tracking-widest text-violet-700">Phase 2 · Activity Vote MVP</p><div class="mt-2 flex flex-wrap items-center justify-between gap-3"><h3 class="font-black text-slate-800">Question Builder และ Lifecycle</h3><span class="rounded-full bg-white px-3 py-1 text-xs font-black">${escHtml(c.Status)}</span></div><div class="mt-4 space-y-3" id="sv-question-list">${state.questions.map((q,i)=>`<div class="rounded-xl border bg-white p-4"><div class="grid gap-3 md:grid-cols-[1fr_180px]"><input data-sv-q-title="${i}" value="${escHtml(q.title)}" class="min-h-[44px] rounded-lg border px-3" placeholder="คำถาม"><select data-sv-q-type="${i}" class="min-h-[44px] rounded-lg border px-3">${options(questionTypes,q.questionType)}</select></div><textarea data-sv-q-options="${i}" rows="3" class="mt-3 w-full rounded-lg border p-3" placeholder="ตัวเลือก บรรทัดละหนึ่งรายการ">${escHtml((q.options||[]).map(o=>o.label).join('\n'))}</textarea><div class="mt-3 grid gap-2 md:grid-cols-3"><input data-sv-q-condition-code="${i}" value="${escHtml(q.displayCondition?.questionCode||'')}" class="min-h-[44px] rounded-lg border px-3 text-xs" placeholder="Condition question code"><select data-sv-q-condition-op="${i}" class="min-h-[44px] rounded-lg border px-3 text-xs"><option value="">No condition</option>${options(['includes','not_includes','equals','not_equals','answered','not_answered'],q.displayCondition?.operator||'')}</select><input data-sv-q-condition-value="${i}" value="${escHtml(q.displayCondition?.value||'')}" class="min-h-[44px] rounded-lg border px-3 text-xs" placeholder="Condition value"></div><div class="mt-3 grid gap-2 sm:grid-cols-2">${(q.options||[]).map((o,j)=>`<label class="rounded-lg border bg-slate-50 p-3 text-xs"><strong class="block truncate">${escHtml(o.label)}</strong><span class="mt-1 block text-slate-500">${o.fileId?`Private image #${Number(o.fileId)}`:'ยังไม่มีภาพ'}</span><input type="file" accept="image/jpeg,image/png,image/webp,image/gif" onchange="window._svUploadOption(${i},${j},event)" class="mt-2 block w-full text-xs"></label>`).join('')}</div><button type="button" onclick="window._svRemoveQuestion(${i})" class="mt-2 min-h-[44px] text-xs font-bold text-rose-600">ลบคำถาม</button></div>`).join('')||'<p class="text-sm text-slate-500">เพิ่มคำถาม single/multiple choice สำหรับ image contest pilot</p>'}</div><div class="mt-4 flex flex-wrap gap-2"><button type="button" onclick="window._svAddQuestion()" class="min-h-[44px] rounded-lg border bg-white px-4 text-xs font-black">+ คำถาม</button><button type="button" onclick="window._svSaveBuilder()" class="min-h-[44px] rounded-lg bg-violet-700 px-4 text-xs font-black text-white">บันทึก Builder</button><button type="button" onclick="window._svFreeze()" class="min-h-[44px] rounded-lg bg-sky-700 px-4 text-xs font-black text-white">Freeze Eligibility</button>${c.Status==='Draft'?'<button type="button" onclick="window._svLifecycle(\'open\')" class="min-h-[44px] rounded-lg bg-emerald-600 px-4 text-xs font-black text-white">Open</button>':''}${c.Status==='Open'?'<button type="button" onclick="window._svLifecycle(\'close\')" class="min-h-[44px] rounded-lg bg-amber-600 px-4 text-xs font-black text-white">Close</button>':''}${c.Status==='Closed'?'<button type="button" onclick="window._svLifecycle(\'publish\')" class="min-h-[44px] rounded-lg bg-slate-900 px-4 text-xs font-black text-white">Publish</button>':''}<button type="button" onclick="window._svReviewQueues()" class="min-h-[44px] rounded-lg border bg-white px-4 text-xs font-black">Review Queue</button><button type="button" onclick="window._svDashboard()" class="min-h-[44px] rounded-lg border bg-white px-4 text-xs font-black">Dashboard</button><button type="button" onclick="window._svExcel()" class="min-h-[44px] rounded-lg border bg-white px-4 text-xs font-black">Excel</button><button type="button" onclick="window._svPdf()" class="min-h-[44px] rounded-lg border bg-white px-4 text-xs font-black">PDF</button></div><div id="sv-admin-dashboard">${state.dashboard?`<div class="mt-5 grid grid-cols-3 gap-3 text-center">${[['Eligible',state.dashboard.eligibleCount],['Voted',state.dashboard.participationCount],['Turnout',state.dashboard.turnoutPct+'%']].map(([l,v])=>`<div class="rounded-xl border bg-white p-3"><strong class="text-xl">${v}</strong><p class="text-xs text-slate-500">${l}</p></div>`).join('')}</div>`:''}</div>`;container.querySelector('.animate-fade-in')?.appendChild(panel);if(state.submissions.length||state.nominations.length){const review=document.createElement('section');review.className='rounded-xl border bg-white p-5';review.innerHTML=`<h3 class="font-black">Submission / Nomination Review</h3><div class="mt-3 grid gap-3 md:grid-cols-2"><div><h4 class="text-sm font-bold">Submissions</h4>${state.submissions.map(x=>`<div class="mt-2 rounded-lg border p-3 text-sm"><strong>${escHtml(x.Title||x.title)}</strong><p>${escHtml(x.Status||x.status)}</p><div class="mt-2 flex gap-2"><button onclick="window._svReviewSubmission(${x.id},'Accepted')" class="min-h-[44px] rounded border px-3">Accept</button><button onclick="window._svFinalSubmission(${x.id})" class="min-h-[44px] rounded border px-3">Finalist</button></div></div>`).join('')}</div><div><h4 class="text-sm font-bold">Nominations</h4>${state.nominations.map(x=>`<div class="mt-2 rounded-lg border p-3 text-sm"><strong>${escHtml(x.NomineeNameSnapshot||x.nomineeNameSnapshot)}</strong><p>${escHtml(x.Status||x.status)} · consent ${escHtml(x.ConsentState||x.consentState)}</p><div class="mt-2 flex gap-2"><button onclick="window._svReviewNomination(${x.id},'Accepted')" class="min-h-[44px] rounded border px-3">Accept</button><button onclick="window._svFinalNomination(${x.id})" class="min-h-[44px] rounded border px-3">Finalist</button></div></div>`).join('')}</div></div>`;container.querySelector('.animate-fade-in')?.appendChild(review);}}

function renderPhase4(container){const c=state.selected?.campaign;if(!c)return;const panel=document.createElement('section');panel.id='sv-phase4-admin';panel.className='rounded-xl border border-indigo-200 bg-indigo-50/40 p-5';panel.innerHTML=`<p class="text-xs font-black uppercase tracking-widest text-indigo-700">Phase 4 · Jury / Scoring / Multi-stage</p><div class="mt-2 flex flex-wrap items-center justify-between gap-3"><h3 class="font-black">Stage, Jury and Result Control</h3><span class="rounded-full bg-white px-3 py-1 text-xs font-black">${state.stages.length} stages · ${state.juryAssignments.length} assignments</span></div><div class="mt-4 grid gap-4 lg:grid-cols-3"><div class="rounded-xl border bg-white p-4"><h4 class="font-bold">Stages</h4>${state.stages.map(x=>`<p class="mt-2 text-sm">${x.SequenceNo||x.sequenceNo}. ${escHtml(x.StageName||x.stageName)}</p>`).join('')||'<p class="mt-2 text-sm text-slate-400">No stages</p>'}<button onclick="window._svConfigureStages()" class="mt-3 min-h-[44px] rounded-lg border px-3 text-xs font-black">Configure 2-stage flow</button></div><div class="rounded-xl border bg-white p-4"><h4 class="font-bold">Scoring Criteria</h4>${state.criteria.map(x=>`<p class="mt-2 text-sm">${escHtml(x.Title||x.title)} · weight ${x.Weight||x.weight}</p>`).join('')||'<p class="mt-2 text-sm text-slate-400">No criteria</p>'}<button onclick="window._svConfigureCriteria()" class="mt-3 min-h-[44px] rounded-lg border px-3 text-xs font-black">Configure criteria</button></div><div class="rounded-xl border bg-white p-4"><h4 class="font-bold">Jury / Result</h4><p class="mt-2 text-sm">Submitted: ${state.juryAssignments.filter(x=>(x.Status||x.status)==='Submitted').length}</p><div class="mt-3 flex flex-wrap gap-2"><button onclick="window._svAssignJury()" class="min-h-[44px] rounded-lg border px-3 text-xs font-black">Assign Juror</button><button onclick="window._svJuryProgress()" class="min-h-[44px] rounded-lg border px-3 text-xs font-black">Progress</button><button onclick="window._svCalculateResult()" class="min-h-[44px] rounded-lg bg-indigo-700 px-3 text-xs font-black text-white">Calculate</button></div></div></div>${state.resultSnapshots.length?`<div class="mt-4 overflow-x-auto"><table class="min-w-[720px] w-full bg-white text-sm"><thead><tr><th class="p-3 text-left">Snapshot</th><th>Status</th><th>Quorum</th><th>Hash</th><th>Actions</th></tr></thead><tbody>${state.resultSnapshots.map(x=>`<tr class="border-t"><td class="p-3">#${x.SnapshotNo}</td><td>${x.Status}</td><td>${x.QuorumState}</td><td class="font-mono text-xs">${escHtml(String(x.ResultHash||'').slice(0,12))}…</td><td><button onclick="window._svFreezeResult(${x.id})" class="min-h-[44px] px-2">Freeze</button><button onclick="window._svCertifyResult(${x.id},'${x.ResultHash}')" class="min-h-[44px] px-2">Certify</button><button onclick="window._svPublishResult(${x.id})" class="min-h-[44px] px-2">Publish</button></td></tr>`).join('')}</tbody></table></div>`:''}`;container.querySelector('.animate-fade-in')?.appendChild(panel);}

function renderPhase4Scoring(container){if(!state.selected?.campaign)return;const cfg=state.scoring||{};const panel=document.createElement('section');panel.className='rounded-xl border border-indigo-200 bg-white p-5';panel.innerHTML=`<div class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-xs font-black uppercase tracking-widest text-indigo-700">Scoring policy</p><h3 class="mt-1 font-black">Weighted / Hybrid / Ranking / Allocation</h3></div><button type="button" onclick="window._svLoadPhase4()" class="min-h-[44px] rounded-lg border px-4 text-xs font-black">Refresh</button></div><div class="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><label class="text-xs font-bold">Method<select id="sv-score-method" class="mt-1 min-h-[44px] w-full rounded-lg border px-3">${options(['weighted_jury','hybrid','rank_points','allocation'],cfg.method||'weighted_jury')}</select></label>${field('sv-jury-weight','Jury weight',cfg.juryWeight??100,'number')}${field('sv-popular-weight','Popular weight',cfg.popularWeight??0,'number')}${field('sv-score-topn','Advance Top N',cfg.topN??1,'number')}${field('sv-score-threshold','Score threshold',cfg.threshold??0,'number')}${field('sv-score-jurors','Minimum jurors',cfg.minJurors??1,'number')}${field('sv-score-participation','Minimum participation',cfg.minParticipation??0,'number')}<label class="text-xs font-bold">Tie-break<select id="sv-score-tie" class="mt-1 min-h-[44px] w-full rounded-lg border px-3">${options(['candidate_id','jury_score','popular_score'],cfg.tieBreak||'candidate_id')}</select></label></div><label class="mt-3 flex min-h-[44px] items-center gap-2 text-sm font-bold"><input id="sv-score-exclude" type="checkbox" ${cfg.excludeHighLow?'checked':''} class="h-5 w-5"> Exclude highest/lowest when at least 3 jurors</label><button type="button" onclick="window._svConfigureScoring()" class="mt-3 min-h-[44px] rounded-lg bg-indigo-700 px-4 text-xs font-black text-white">Save scoring policy</button>`;container.querySelector('.animate-fade-in')?.appendChild(panel);}

function renderPhase5(container){if(!state.selected?.campaign)return;const o=state.operations,f=o?.funnel||{},metric=x=>x?.suppressed?'Suppressed':Number(x?.value||0).toLocaleString(),panel=document.createElement('section');panel.id='sv-phase5-operations';panel.className='rounded-xl border border-cyan-200 bg-cyan-50/40 p-5';panel.innerHTML=`<div class="flex flex-wrap items-center justify-between gap-3"><div><p class="text-xs font-black uppercase tracking-widest text-cyan-700">Phase 5 · Operations / Analytics</p><h3 class="mt-1 font-black">Campaign Operations Center</h3></div><span class="rounded-full bg-white px-3 py-1 text-xs font-black">${escHtml(o?.campaign?.timeZone||'Asia/Bangkok')}</span></div><div class="mt-4 grid grid-cols-2 gap-3 md:grid-cols-4">${[['Eligible',f.eligible],['Started',f.started],['Submitted',f.submitted],['Accepted',f.accepted]].map(([l,x])=>`<div class="rounded-xl border bg-white p-3"><strong class="text-xl">${metric(x)}</strong><p class="text-xs text-slate-500">${l}</p></div>`).join('')}</div><p class="mt-3 text-sm">Reconciliation: <strong>${escHtml(f.reconciliation||'—')}</strong> · Timeline ${o?.timeline?.length||0} events</p><div class="mt-4 flex flex-wrap gap-2"><button onclick="window._svProcessSchedule()" class="min-h-[44px] rounded-lg border bg-white px-3 text-xs font-black">Process schedule</button><button onclick="window._svPreviewNotifications()" class="min-h-[44px] rounded-lg border bg-white px-3 text-xs font-black">Preview reminders</button><button onclick="window._svQueueNotifications()" class="min-h-[44px] rounded-lg border bg-white px-3 text-xs font-black">Queue reminders</button><button onclick="window._svDispatchNotifications()" class="min-h-[44px] rounded-lg border bg-white px-3 text-xs font-black">Dispatch fixture</button><button onclick="window._svPhase5Export('excel')" class="min-h-[44px] rounded-lg bg-cyan-700 px-3 text-xs font-black text-white">Aggregate Excel</button><button onclick="window._svPhase5Export('pdf')" class="min-h-[44px] rounded-lg bg-cyan-700 px-3 text-xs font-black text-white">Aggregate PDF</button><button onclick="window._svCertifiedReport()" class="min-h-[44px] rounded-lg bg-slate-900 px-3 text-xs font-black text-white">Certified report</button></div>${state.notificationPreview?`<p class="mt-3 rounded-lg bg-white p-3 text-sm">Reminder audience: ${Number(state.notificationPreview.total||0)} · ${escHtml(state.notificationPreview.audience||'')}</p>`:''}`;container.querySelector('.animate-fade-in')?.appendChild(panel);}

function renderPhase6(container){const c=state.selected?.campaign;if(!c||c.CampaignType!=='secret_election')return;const panel=document.createElement('section');panel.id='sv-phase6-secret-election';panel.className='rounded-xl border border-amber-300 bg-amber-50 p-5';panel.innerHTML=`<div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-black uppercase tracking-widest text-amber-800">Phase 6 · Certified Secret Election</p><h3 class="mt-1 font-black">Secret Election Control Room</h3></div><span class="rounded-full bg-white px-3 py-1 text-xs font-black">${escHtml(c.Status)} · ${escHtml(c.PrivacyMode)}</span></div><div class="mt-4 grid gap-3 md:grid-cols-3"><div class="rounded-xl border bg-white p-4"><strong>Privacy boundary</strong><p class="mt-2 text-xs text-slate-600">Participation and ballot are separated. Receipt proves acceptance only. Database/server operator anonymity requires separate organizational controls.</p></div><div class="rounded-xl border bg-white p-4"><strong>Dual control</strong><p class="mt-2 text-xs text-slate-600">Two independently assigned certifiers must bind the exact immutable result hash before publication.</p></div><div class="rounded-xl border bg-white p-4"><strong>Result gate</strong><p class="mt-2 text-xs text-slate-600">No result before close, balanced recount, resolved ties, certification and explicit publication.</p></div></div><div class="mt-4 flex flex-wrap gap-2"><button onclick="window._svConfigureElection()" class="min-h-[44px] rounded-lg border bg-white px-3 text-xs font-black">Build positions/seats</button><button onclick="window._svAssignCertifier()" class="min-h-[44px] rounded-lg border bg-white px-3 text-xs font-black">Assign certifier</button><button onclick="window._svSecretRecount()" class="min-h-[44px] rounded-lg bg-amber-700 px-3 text-xs font-black text-white">Deterministic recount</button><button onclick="window._svSecretVoid()" class="min-h-[44px] rounded-lg border border-rose-300 bg-white px-3 text-xs font-black text-rose-700">Void election</button></div></section>`;container.querySelector('.animate-fade-in')?.appendChild(panel);}

function renderPhase7(container){const c=state.selected?.campaign;if(!c)return;const g=state.governance,v=g?.verification,p=g?.preflight,o=g?.observability,pill=x=>x?'PASS':'BLOCK',panel=document.createElement('section');panel.id='sv-phase7-governance';panel.className='rounded-xl border border-fuchsia-300 bg-fuchsia-50/50 p-5';panel.innerHTML=`<div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-black uppercase tracking-widest text-fuchsia-800">Phase 7 · SHE Internal Governance</p><h3 class="mt-1 font-black">Release Candidate Control</h3></div><span class="rounded-full bg-white px-3 py-1 text-xs font-black">${escHtml(p?.decision||'NOT CHECKED')}</span></div><div class="mt-4 grid gap-3 md:grid-cols-3"><div class="rounded-xl border bg-white p-4"><strong>Hash verification</strong><p class="mt-2 text-xs">${pill(v?.ready)} · ${v?.checks?.length||0} checks · identities ${Number(v?.identityMappings||0)}</p></div><div class="rounded-xl border bg-white p-4"><strong>SHE approval</strong><p class="mt-2 text-xs">Owner: SHE · Missing: ${escHtml((p?.missingAcceptance||[]).join(', ')||'none')}</p></div><div class="rounded-xl border bg-white p-4"><strong>Observability</strong><p class="mt-2 text-xs">Delivered ${Number(o?.handoffs?.delivered||0)} · Open alerts ${Number(o?.openAlerts||0)}</p></div></div><p class="mt-3 rounded-lg border bg-white p-3 text-xs text-slate-600">Campaign approval is controlled internally by SHE. Secret Election still requires two independent certifiers. System Control/HR, calendar and notification adapters remain read-only, and handoff never includes voter identity, receipt or ballot choice.</p><div class="mt-4 flex flex-wrap gap-2"><button onclick="window._svApproveShe()" class="min-h-[44px] rounded-lg bg-emerald-700 px-3 text-xs font-black text-white">Approve by SHE</button><button onclick="window._svLoadPhase7()" class="min-h-[44px] rounded-lg border bg-white px-3 text-xs font-black">Run read-only preflight</button><button onclick="window._svPreviewHandoff()" class="min-h-[44px] rounded-lg bg-fuchsia-700 px-3 text-xs font-black text-white">Preview certified handoff</button></div>${state.handoffPreview?`<div class="mt-4 rounded-xl border bg-white p-4 text-xs"><strong>Preview hash</strong><p class="mt-1 break-all font-mono">${escHtml(state.handoffPreview.previewHash)}</p><p class="mt-2">Required phrase: <code>${escHtml(state.handoffPreview.confirmation)}</code></p><button onclick="window._svConfirmHandoff()" class="mt-3 min-h-[44px] rounded-lg bg-slate-900 px-3 font-black text-white">Confirm fixture handoff</button></div>`:''}</section>`;container.querySelector('.animate-fade-in')?.appendChild(panel);}

function campaignPayload() { return { campaignCode:document.getElementById('sv-code')?.value,titleTh:document.getElementById('sv-title-th')?.value,titleEn:document.getElementById('sv-title-en')?.value,campaignType:document.getElementById('sv-type')?.value,privacyMode:document.getElementById('sv-privacy')?.value,resultVisibility:document.getElementById('sv-result')?.value,privacyThreshold:Number(document.getElementById('sv-threshold')?.value||5),summary:document.getElementById('sv-summary')?.value,discoveryMode:'eligible_only' }; }
function bind(container) {
    window._svNew=()=>{state.editing=null;render(container);};
    window._svSave=async()=>{try{const payload=campaignPayload();if(state.editing?.id)await API.put(`/safety-vote/admin/campaigns/${state.editing.id}`,{...payload,rowVersion:state.editing.rowVersion});else await API.post('/safety-vote/admin/campaigns',payload);showToast('บันทึก Draft Campaign แล้ว','success');await load(container);}catch(e){showError(e.message||'บันทึก Draft ไม่สำเร็จ');}};
    window._svSelect=async id=>{try{const [res,builder]=await Promise.all([API.get(`/safety-vote/admin/campaigns/${id}`),API.get(`/safety-vote/admin/campaigns/${id}/builder`)]);state.selected=res.data;state.questions=builder.data.questions||[];state.rules=(res.data.eligibilityRules||[]).map(r=>({effect:r.Effect||r.effect,attributeKey:r.AttributeKey||r.attributeKey,operator:r.Operator||r.operator,values:r.values||[],reason:r.Reason||r.reason||null}));const c=res.data.campaign;state.editing={id:Number(c.id),rowVersion:Number(c.RowVersion),campaignCode:c.CampaignCode,titleTh:c.TitleTh,titleEn:c.TitleEn,campaignType:c.CampaignType,privacyMode:c.PrivacyMode,resultVisibility:c.ResultVisibility,privacyThreshold:c.PrivacyThreshold,summary:c.Summary};state.preview=null;state.dashboard=null;render(container);await window._svLoadPhase4();}catch(e){showError(e.message||'โหลด Campaign ไม่สำเร็จ');}};
    window._svAddRule=()=>{const attr=document.getElementById('sv-rule-attr')?.value,raw=document.getElementById('sv-rule-values')?.value||'';state.rules.push({effect:document.getElementById('sv-rule-effect')?.value,attributeKey:attr,operator:document.getElementById('sv-rule-op')?.value,values:attr==='all'?['all']:raw.split(',').map(v=>v.trim()).filter(Boolean),reason:'Admin rule'});render(container);};
    window._svRemoveRule=index=>{state.rules.splice(index,1);render(container);};
    window._svVoid=async()=>{const reason=window.prompt('เหตุผลที่ยกเลิก Draft');if(!reason)return;try{await API.delete(`/safety-vote/admin/campaigns/${state.editing.id}`,{body:JSON.stringify({reason})});showToast('ยกเลิก Draft และเก็บประวัติแล้ว','success');state.editing=null;state.selected=null;await load(container);}catch(e){showError(e.message||'ยกเลิก Draft ไม่สำเร็จ');}};
    window._svSaveRules=async()=>{try{await API.put(`/safety-vote/admin/campaigns/${state.selected.campaign.id}/eligibility/rules`,{rules:state.rules});showToast('บันทึก Eligibility rules แล้ว','success');}catch(e){showError(e.message||'บันทึกกฎไม่สำเร็จ');}};
    window._svPreview=async()=>{try{const res=await API.post(`/safety-vote/admin/campaigns/${state.selected.campaign.id}/eligibility/preview`,{rules:state.rules});state.preview=res.data;render(container);}catch(e){showError(e.message||'Preview ไม่สำเร็จ');}};
    window._svMasterSearch=async()=>{try{const q=encodeURIComponent(document.getElementById('sv-master-q')?.value||'');const res=await API.get(`/safety-vote/admin/master/employees?q=${q}&pageSize=50`);state.employees=res.data.rows||[];render(container);}catch(e){showError(e.message||'ค้นหา Master Data ไม่สำเร็จ');}};
    window._svAddQuestion=()=>{state.questions.push({questionCode:`Q${state.questions.length+1}`,questionType:'single_choice',title:'',isRequired:true,minSelections:1,maxSelections:1,options:[{label:''},{label:''}]});render(container);};
    window._svRemoveQuestion=i=>{state.questions.splice(i,1);render(container);};
    window._svSaveBuilder=async()=>{try{const questions=state.questions.map((q,i)=>{const type=document.querySelector(`[data-sv-q-type="${i}"]`)?.value||q.questionType,lines=(document.querySelector(`[data-sv-q-options="${i}"]`)?.value||'').split('\n').map(x=>x.trim()).filter(Boolean);const conditionCode=document.querySelector(`[data-sv-q-condition-code="${i}"]`)?.value.trim(),conditionOp=document.querySelector(`[data-sv-q-condition-op="${i}"]`)?.value,conditionValue=document.querySelector(`[data-sv-q-condition-value="${i}"]`)?.value;return{questionCode:q.questionCode||`Q${i+1}`,questionType:type,title:document.querySelector(`[data-sv-q-title="${i}"]`)?.value||'',isRequired:true,minSelections:1,maxSelections:['single_choice','yes_no_abstain','rating','short_text','long_text','date_time','employee_picker','organization_picker','file_upload'].includes(type)?1:Math.max(1,lines.length),validation:type==='rating'?{minNumber:1,maxNumber:5}:{},displayCondition:conditionCode&&conditionOp?{questionCode:conditionCode,operator:conditionOp,value:conditionValue}:null,sortOrder:i+1,options:optionQuestionTypes.has(type)?lines.map((label,j)=>({optionCode:`O${j+1}`,label,fileId:q.options?.[j]?.fileId||null,sortOrder:j+1})):[]};});const r=await API.put(`/safety-vote/admin/campaigns/${state.editing.id}/builder`,{questions});state.questions=r.data.questions;showToast('บันทึก Question Builder แล้ว','success');render(container);}catch(e){showError(e.message||'บันทึก Builder ไม่สำเร็จ');}};
    window._svUploadOption=async(qi,oi,event)=>{const file=event.target.files?.[0];if(!file)return;try{const form=new FormData();form.append('file',file);form.append('purpose','option_image');const r=await API.upload(`/safety-vote/admin/campaigns/${state.editing.id}/files`,form);state.questions[qi].options[oi].fileId=Number(r.data.id);showToast('อัปโหลดภาพแบบ private แล้ว กรุณาบันทึก Builder','success');render(container);}catch(e){showError(e.message||'อัปโหลดภาพไม่สำเร็จ');}};
    window._svFreeze=async()=>{try{const r=await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/eligibility/freeze`,{reason:'Admin Phase 2 preflight'});showToast(`Freeze ผู้มีสิทธิ์ ${r.data.eligibleCount} คนแล้ว`,'success');}catch(e){showError(e.message||'Freeze Eligibility ไม่สำเร็จ');}};
    window._svLifecycle=async command=>{try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/lifecycle/${command}`,{});showToast(`Lifecycle ${command} สำเร็จ`,'success');await load(container);}catch(e){showError(e.message||'เปลี่ยนสถานะไม่สำเร็จ');}};
    window._svDashboard=async()=>{try{const r=await API.get(`/safety-vote/admin/campaigns/${state.editing.id}/dashboard`);state.dashboard=r.data;render(container);}catch(e){showError(e.message||'โหลด Dashboard ไม่สำเร็จ');}};
    window._svReviewQueues=async()=>{try{const id=state.editing.id,[s,n]=await Promise.all([API.get(`/safety-vote/admin/campaigns/${id}/submissions`),API.get(`/safety-vote/admin/campaigns/${id}/nominations`)]);state.submissions=s.data.rows||[];state.nominations=n.data.rows||[];render(container);}catch(e){showError(e.message||'โหลด Review Queue ไม่สำเร็จ');}};
    window._svReviewSubmission=async(id,decision)=>{const reason=window.prompt('เหตุผลการพิจารณา');if(!reason)return;try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/submissions/${id}/review`,{decision,reason});await window._svReviewQueues();}catch(e){showError(e.message||'Review ไม่สำเร็จ');}};
    window._svFinalSubmission=async id=>{const reason=window.prompt('เหตุผลที่เลือกเป็น Finalist');if(!reason)return;try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/submissions/${id}/finalist`,{reason});await window._svReviewQueues();}catch(e){showError(e.message||'เลือก Finalist ไม่สำเร็จ');}};
    window._svReviewNomination=async(id,decision)=>{const reason=window.prompt('เหตุผลการพิจารณา');if(!reason)return;try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/nominations/${id}/review`,{decision,reason});await window._svReviewQueues();}catch(e){showError(e.message||'Review ไม่สำเร็จ');}};
    window._svFinalNomination=async id=>{const reason=window.prompt('เหตุผลที่เลือกเป็น Finalist');if(!reason)return;try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/nominations/${id}/finalist`,{reason});await window._svReviewQueues();}catch(e){showError(e.message||'เลือก Finalist ไม่สำเร็จ');}};
    window._svLoadPhase4=async()=>{const id=state.editing.id,[sc,st,cr,as,rs,op]=await Promise.allSettled([API.get(`/safety-vote/admin/campaigns/${id}/scoring`),API.get(`/safety-vote/admin/campaigns/${id}/stages`),API.get(`/safety-vote/admin/campaigns/${id}/jury/criteria`),API.get(`/safety-vote/admin/campaigns/${id}/jury/assignments`),API.get(`/safety-vote/admin/campaigns/${id}/results/snapshots`),API.get(`/safety-vote/admin/campaigns/${id}/operations`)]);state.scoring=sc.value?.data?.config||null;state.stages=st.value?.data?.rows||[];state.criteria=cr.value?.data?.rows||[];state.juryAssignments=as.value?.data?.rows||[];state.resultSnapshots=rs.value?.data?.rows||[];state.operations=op.value?.data||null;render(container);if([sc,st,cr,as,rs,op].some(x=>x.status==='rejected'||!x.value?.data))showError('โหลดข้อมูล Operations บางส่วนไม่สำเร็จ');};
    window._svConfigureScoring=async()=>{try{const value=id=>Number(document.getElementById(id)?.value||0),config={method:document.getElementById('sv-score-method')?.value,juryWeight:value('sv-jury-weight'),popularWeight:value('sv-popular-weight'),topN:value('sv-score-topn'),threshold:value('sv-score-threshold'),minJurors:value('sv-score-jurors'),minParticipation:value('sv-score-participation'),tieBreak:document.getElementById('sv-score-tie')?.value,excludeHighLow:Boolean(document.getElementById('sv-score-exclude')?.checked)},r=await API.put(`/safety-vote/admin/campaigns/${state.editing.id}/scoring`,{config});state.scoring=r.data.config;showToast('บันทึก scoring policy แล้ว','success');render(container);}catch(e){showError(e.message||'บันทึก scoring policy ไม่สำเร็จ');}};
    window._svConfigureStages=async()=>{try{await API.put(`/safety-vote/admin/campaigns/${state.editing.id}/stages`,{stages:[{stageKey:'QUALIFY',stageName:'Qualifying',stageType:'hybrid',sequenceNo:1,advanceRule:{topN:3,threshold:60,blind:true},resultVisibility:'admin_only'},{stageKey:'FINAL',stageName:'Final',stageType:'jury',sequenceNo:2,advanceRule:{topN:1,threshold:70,blind:true},resultVisibility:'certified_only'}]});showToast('บันทึก Multi-stage แล้ว','success');await window._svLoadPhase4();}catch(e){showError(e.message||'บันทึก Stage ไม่สำเร็จ');}};
    window._svConfigureCriteria=async()=>{const stage=state.stages[0]?.id;if(!stage)return showError('กรุณาสร้าง Stage ก่อน');try{await API.put(`/safety-vote/admin/campaigns/${state.editing.id}/jury/criteria`,{stageId:Number(stage),criteria:[{criterionCode:'SAFETY',title:'Safety impact',minScore:0,maxScore:10,weight:60},{criterionCode:'PRACTICAL',title:'Practical implementation',minScore:0,maxScore:10,weight:40}]});showToast('บันทึกเกณฑ์แล้ว','success');await window._svLoadPhase4();}catch(e){showError(e.message||'บันทึกเกณฑ์ไม่สำเร็จ');}};
    window._svAssignJury=async()=>{const stage=state.stages[0]?.id,juror=prompt('Employee ID ของกรรมการ');if(!stage||!juror)return;try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/jury/assignments`,{stageId:Number(stage),jurorEmployeeId:juror});showToast('มอบหมายกรรมการแล้ว','success');await window._svLoadPhase4();}catch(e){showError(e.message||'มอบหมายกรรมการไม่สำเร็จ');}};
    window._svJuryProgress=async()=>{try{const r=await API.get(`/safety-vote/admin/campaigns/${state.editing.id}/jury/progress`);showToast(`Jury progress: ${(r.data.rows||[]).map(x=>`${x.Status} ${x.total}`).join(', ')||'none'}`,'info');}catch(e){showError(e.message||'โหลด Progress ไม่สำเร็จ');}};
    window._svCalculateResult=async()=>{const stage=state.stages[0]?.id;if(!stage)return showError('กรุณาสร้าง Stage ก่อน');try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/results/calculate`,{stageId:Number(stage)});showToast('สร้าง immutable result snapshot แล้ว','success');await window._svLoadPhase4();}catch(e){showError(e.message||'คำนวณผลไม่สำเร็จ');}};
    window._svFreezeResult=async id=>{try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/results/${id}/freeze`,{});await window._svLoadPhase4();}catch(e){showError(e.message||'Freeze ผลไม่สำเร็จ');}};
    window._svCertifyResult=async(id,resultHash)=>{const reason=prompt('เหตุผลรับรองผล');if(!reason)return;try{const command=state.selected?.campaign?.CampaignType==='secret_election'?'certify-secret':'certify';await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/results/${id}/${command}`,{resultHash,reason});await window._svLoadPhase4();}catch(e){showError(e.message||'รับรองผลไม่สำเร็จ');}};
    window._svPublishResult=async id=>{try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/results/${id}/publish`,{});await window._svLoadPhase4();}catch(e){showError(e.message||'Publish ผลไม่สำเร็จ');}};
    window._svProcessSchedule=async()=>{try{await API.post('/safety-vote/admin/operations/process-due',{});await window._svLoadPhase4();}catch(e){showError(e.message||'ประมวลผล Schedule ไม่สำเร็จ');}};
    window._svPreviewNotifications=async()=>{try{const r=await API.get(`/safety-vote/admin/campaigns/${state.editing.id}/notifications/preview?audience=nonparticipants`);state.notificationPreview=r.data;render(container);}catch(e){showError(e.message||'Preview reminder ไม่สำเร็จ');}};
    window._svQueueNotifications=async()=>{try{const r=await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/notifications/queue`,{audience:'nonparticipants',eventType:'reminder',templateKey:'vote_reminder',channel:'in_app',windowKey:new Date().toISOString().slice(0,10),metadata:{route:'#safety-vote'}});showToast(`Queued ${r.data.queued}, suppressed ${r.data.suppressed}`,'success');await window._svLoadPhase4();}catch(e){showError(e.message||'Queue reminder ไม่สำเร็จ');}};
    window._svDispatchNotifications=async()=>{try{const r=await API.post('/safety-vote/admin/notifications/dispatch',{limit:25});showToast(`Sent ${r.data.sent}, failed ${r.data.failed}`,'success');await window._svLoadPhase4();}catch(e){showError(e.message||'Dispatch ไม่สำเร็จ');}};
    window._svPhase5Export=async format=>{const snapshot=state.resultSnapshots[0]?.id;if(!snapshot)return showError('ยังไม่มี result snapshot');try{const r=await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/exports`,{snapshotId:Number(snapshot),format});showToast(`${format.toUpperCase()} ${r.data.report.reportId} พร้อมแล้ว`,'success');await window._svLoadPhase4();}catch(e){showError(e.message||'Export ไม่สำเร็จ');}};
    window._svCertifiedReport=async()=>{const snapshot=state.resultSnapshots.find(x=>['Certified','Published'].includes(x.Status))?.id;if(!snapshot)return showError('ยังไม่มี certified snapshot');try{const r=await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/exports/certified-report`,{snapshotId:Number(snapshot),format:'pdf'});showToast(`Certified report ${r.data.reportId}`,'success');await window._svLoadPhase4();}catch(e){showError(e.message||'สร้าง Certified report ไม่สำเร็จ');}};
    window._svConfigureElection=async()=>{try{const positions=state.questions.map((q,i)=>({positionCode:q.questionCode||`POSITION_${i+1}`,questionId:Number(q.id),title:q.title,seatCount:Number(prompt(`จำนวนที่นั่ง: ${q.title}`,'1')||1),maxSelections:Number(prompt(`เลือกได้สูงสุด: ${q.title}`,'1')||1),allowAbstain:true,tieRule:'unresolved',sortOrder:i+1,candidateIds:(q.options||[]).map(o=>Number(o.candidateId)).filter(Boolean)}));if(positions.some(x=>!x.questionId||x.candidateIds.length<x.seatCount))return showError('ทุกตำแหน่งต้องมี Question และ Candidate ครบตามจำนวนที่นั่ง');await API.put(`/safety-vote/admin/campaigns/${state.editing.id}/election`,{positions});showToast('บันทึกตำแหน่ง ที่นั่ง Abstain และ tie rule แล้ว','success');}catch(e){showError(e.message||'บันทึก Secret Election configuration ไม่สำเร็จ');}};
    window._svAssignCertifier=async()=>{const employeeId=prompt('Employee ID ผู้รับรองผล'),controlRole=prompt('Control role: primary หรือ secondary','primary');if(!employeeId||!controlRole)return;try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/certifiers`,{employeeId,controlRole});showToast('มอบหมายผู้รับรองผลแล้ว','success');}catch(e){showError(e.message||'มอบหมายผู้รับรองผลไม่สำเร็จ');}};
    window._svSecretRecount=async()=>{const reason=prompt('เหตุผลการนับ/นับใหม่');if(!reason)return;try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/results/recount`,{reason});showToast('สร้าง immutable recount snapshot แล้ว','success');await window._svLoadPhase4();}catch(e){showError(e.message||'Recount ไม่สำเร็จ');}};
    window._svSecretVoid=async()=>{const reason=prompt('เหตุผลการประกาศให้การเลือกตั้งเป็นโมฆะ');if(!reason)return;try{await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/void`,{reason});showToast('Voided โดยเก็บข้อมูลและ audit ทั้งหมด','success');await load(container);}catch(e){showError(e.message||'Void election ไม่สำเร็จ');}};
    window._svLoadPhase7=async()=>{try{const id=state.editing.id,[verification,preflight,observability]=await Promise.all([API.get(`/safety-vote/admin/campaigns/${id}/release-verification`),API.get(`/safety-vote/admin/campaigns/${id}/release-preflight`),API.get(`/safety-vote/admin/campaigns/${id}/observability`)]);state.governance={verification:verification.data,preflight:preflight.data,observability:observability.data};render(container);}catch(e){showError(e.message||'โหลด Phase 7 preflight ไม่สำเร็จ');}};
    window._svApproveShe=async()=>{const c=state.selected?.campaign;if(!c)return;const confirmation=`I ACCEPT SHE_OWNER ${c.CampaignCode}`;if(window.prompt(`พิมพ์ข้อความนี้เพื่ออนุมัติภายในฝ่าย SHE:\n${confirmation}`)!==confirmation)return;try{await API.post(`/safety-vote/admin/campaigns/${c.id}/acceptance-evidence`,{acceptanceArea:'she_owner',decision:'Accepted',evidenceReference:`internal://she/${c.CampaignCode}`,confirmation});showToast('บันทึกการอนุมัติภายในฝ่าย SHE แล้ว','success');await window._svLoadPhase7();}catch(e){showError(e.message||'บันทึกการอนุมัติ SHE ไม่สำเร็จ');}};
    window._svPreviewHandoff=async()=>{const target=prompt('Target adapter: dashboard, committee, hiyari, ky, bbs, patrol, training, policy, johnny, calendar, notification','dashboard');if(!target)return;try{const r=await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/integrations/handoffs/preview`,{targetAdapter:target});state.handoffPreview=r.data;render(container);}catch(e){showError(e.message||'Preview handoff ไม่สำเร็จ');}};
    window._svConfirmHandoff=async()=>{const p=state.handoffPreview;if(!p)return;const confirmation=prompt('พิมพ์คำยืนยันให้ตรงทุกตัวอักษร',p.confirmation);if(!confirmation)return;try{const r=await API.post(`/safety-vote/admin/campaigns/${state.editing.id}/integrations/handoffs/confirm`,{targetAdapter:p.payload.targetAdapter,previewHash:p.previewHash,confirmation});showToast(`Recorded ${r.data.providerReceipt}; external delivery = ${r.data.externalDelivery}`,'success');state.handoffPreview=null;await window._svLoadPhase7();}catch(e){showError(e.message||'Confirm handoff ไม่สำเร็จ');}};
    window._svExcel=async()=>{try{const r=await API.get(`/safety-vote/admin/campaigns/${state.editing.id}/exports/data`),rows=r.data.questions.flatMap(q=>q.options.map(o=>({Campaign:r.data.campaign.title,Question:q.title,Option:o.label,Votes:o.count,Percentage:o.percentage,Eligible:r.data.eligibleCount,Participation:r.data.participationCount})));const ws=XLSX.utils.json_to_sheet(rows),wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,ws,'Safety Vote');XLSX.writeFile(wb,`${r.data.campaign.code}-results.xlsx`);}catch(e){showError(e.message||'Export Excel ไม่สำเร็จ');}};
    window._svPdf=async()=>{try{const r=await API.get(`/safety-vote/admin/campaigns/${state.editing.id}/exports/data`),{jsPDF}=window.jspdf,pdf=new jsPDF();pdf.setFontSize(16);pdf.text('Safety Vote Result',14,18);pdf.setFontSize(10);pdf.text(`${r.data.campaign.code} | ${r.data.campaign.title}`,14,27);pdf.text(`Eligible ${r.data.eligibleCount} | Participation ${r.data.participationCount} | Turnout ${r.data.turnoutPct}%`,14,34);let y=44;for(const q of r.data.questions){pdf.text(q.title.replace(/[^\x20-\x7E]/g,'?'),14,y);y+=6;for(const o of q.options){pdf.text(`- ${o.label.replace(/[^\x20-\x7E]/g,'?')}: ${o.count} (${o.percentage}%)`,18,y);y+=6;if(y>280){pdf.addPage();y=20;}}}pdf.save(`${r.data.campaign.code}-results.pdf`);}catch(e){showError(e.message||'Export PDF ไม่สำเร็จ');}};
}

async function load(container) { const [health,campaigns]=await Promise.all([API.get('/safety-vote/admin/health'),API.get('/safety-vote/admin/campaigns')]);state.health=health.data;state.campaigns=campaigns.data.rows||[];render(container);bind(container); }

export async function renderSafetyVoteFoundation(container) { try { const health=await API.get('/safety-vote/admin/health');state.health=health.data;if(state.health.ready){const campaigns=await API.get('/safety-vote/admin/campaigns');state.campaigns=campaigns.data.rows||[];}render(container);bind(container);} catch (error) { state.health=error.details||error.data||{ready:false,message:error.message};render(container);bind(container); } }
